def longest_subarray_with_k_distinct(nums: List[int], k: int) -> int:
    if not nums or k == 0:
        return 0

    left = right = 0
    distinct_count = 0
    max_length = 0

    while right < len(nums):
        if nums[right] not in nums[left:right]:
            distinct_count += 1

        while distinct_count > k:
            if nums[left] not in nums[left:right]:
